def calculate_material_properties():
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.supercells import get_sc_fromstruct, _ase_cubic
    from pymatgen.core.structure import StructureError
    from pathlib import Path

    results = {
        "supercell_size_constraint": None,
        "supercell_generation_failure": None
    }

    try:
        # Load the GaN structure
        file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")
        gan_struct = Structure.from_file(file_path / "GaN.vasp")

        # Check supercell size constraint
        sc_mat = _ase_cubic(gan_struct, min_atoms=4, max_atoms=8, min_length=1.0)
        sc = gan_struct * sc_mat
        results["supercell_size_constraint"] = 4 <= sc.num_sites <= 8

    except Exception as e:
        results["supercell_size_constraint"] = None

    try:
        # Check supercell generation failure
        try:
            sc_mat_fail = _ase_cubic(gan_struct, min_atoms=4, max_atoms=8, min_length=10.0)
            sc_fail = gan_struct * sc_mat_fail
            results["supercell_generation_failure"] = False
        except RuntimeError:
            results["supercell_generation_failure"] = True

    except Exception as e:
        results["supercell_generation_failure"] = None

    return results

def calculate_material_properties():
    """
    Calculate material properties using Pymatgen.

    Returns:
        dict: A dictionary containing the calculated properties:
            - 'supercell_structure_matching': bool indicating if the supercell structure matches the reference.
            - 'closest_supercell_matrix': list of lists of floats representing the closest supercell matrix.
    """
    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")
    si_o_structs = loadfn(file_path / "Si-O_structs.json")

    ref_sc_mat = [[2, 1, 2], [2, 0, 3], [2, 1, 1]]
    vg = VacancyGenerator()

    def get_vac(s, sc_mat):
        vac = next(vg.generate(s, rm_species=["O"]))
        return vac.get_supercell_structure(sc_mat=sc_mat)

    def check_uc(uc_struct, sc_mat) -> bool:
        vac_sc = get_vac(uc_struct, sc_mat)
        sorted_results = get_closest_sc_mat(uc_struct, vac_sc, debug=True)
        min_dist = sorted_results[0][0]
        close_mats = [r[2] for r in sorted_results if r[0] < min_dist * 1.1]
        is_matched = [np.allclose(ref_sc_mat, x) for x in close_mats]
        return any(is_matched)

    try:
        supercell_structure_matching = all(check_uc(s, ref_sc_mat) for s in si_o_structs)
    except Exception:
        supercell_structure_matching = None

    try:
        uc_struct = si_o_structs[0]
        vac_struct = get_vac(uc_struct, ref_sc_mat)
        closest_supercell_matrix = get_closest_sc_mat(uc_struct, vac_struct, debug=False).tolist()
    except Exception:
        closest_supercell_matrix = None

    return {
        "supercell_structure_matching": supercell_structure_matching,
        "closest_supercell_matrix": closest_supercell_matrix
    }

def calculate_material_properties():
    import os
    from pathlib import Path
    from collections import defaultdict
    from monty.serialization import loadfn
    from pymatgen.analysis.phase_diagram import PhaseDiagram
    from pymatgen.analysis.defects.core import PeriodicSite, Substitution
    from pymatgen.analysis.defects.thermo import DefectEntry, FormationEnergyDiagram
    from pymatgen.core import Element, Structure, Specie
    from pymatgen.io.vasp.outputs import Locpot, Vasprun

    test_dir = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/")

    def gan_struct(test_dir):
        return Structure.from_file(test_dir / "GaN.vasp")

    def data_Mg_Ga(test_dir):
        root_dir = test_dir / "Mg_Ga"
        data = defaultdict(dict)
        for fold in root_dir.glob("./*"):
            if not fold.is_dir():
                continue
            data[fold.name] = {
                "vasprun": Vasprun(fold / "vasprun.xml.gz"),
                "locpot": Locpot.from_file(fold / "LOCPOT.gz"),
            }
        return data

    def defect_Mg_Ga(gan_struct):
        ga_site = gan_struct[0]
        mg_site = PeriodicSite(Specie("Mg"), ga_site.frac_coords, gan_struct.lattice)
        return Substitution(gan_struct, mg_site)

    def defect_entries_and_plot_data_Mg_Ga(data_Mg_Ga, defect_Mg_Ga):
        bulk_locpot = data_Mg_Ga["bulk_sc"]["locpot"]

        def get_data(q):
            computed_entry = data_Mg_Ga[f"q={q}"]["vasprun"].get_computed_entry(
                inc_structure=True
            )
            defect_locpot = data_Mg_Ga[f"q={q}"]["locpot"]

            def_entry = DefectEntry(
                defect=defect_Mg_Ga, charge_state=q, sc_entry=computed_entry
            )
            frey_summary = def_entry.get_freysoldt_correction(
                defect_locpot=defect_locpot, bulk_locpot=bulk_locpot, dielectric=14
            )
            return def_entry, frey_summary

        defect_entries = dict()
        plot_data = dict()
        for qq in [-2, -1, 0, 1]:
            defect_entry, frey_summary = get_data(qq)
            defect_entries[qq] = defect_entry
            plot_data[qq] = frey_summary.metadata["plot_data"]
        return defect_entries, plot_data

    def stable_entries_Mg_Ga_N(test_dir):
        return loadfn(test_dir / "stable_entries_Mg_Ga_N.json")

    def formation_energy_diagram(
        data_Mg_Ga, defect_entries_and_plot_data_Mg_Ga, stable_entries_Mg_Ga_N):
        bulk_vasprun = data_Mg_Ga["bulk_sc"]["vasprun"]
        bulk_bs = bulk_vasprun.get_band_structure()
        vbm = bulk_bs.get_vbm()["energy"]
        bulk_entry = bulk_vasprun.get_computed_entry(inc_structure=False)
        defect_entries, _ = defect_entries_and_plot_data_Mg_Ga

        def_ent_list = list(defect_entries.values())
        atomic_entries = list(
            filter(lambda x: len(x.composition.elements) == 1, stable_entries_Mg_Ga_N)
        )
        pd = PhaseDiagram(stable_entries_Mg_Ga_N)
        fed = FormationEnergyDiagram.with_atomic_entries(
            defect_entries=def_ent_list,
            atomic_entries=atomic_entries,
            vbm=vbm,
            inc_inf_values=False,
            phase_diagram=pd,
            bulk_entry=bulk_entry,
        )
        return fed

    properties = {
        "competing_phases_at_chempot_limits": None
    }

    try:
        gan_structure = gan_struct(test_dir)
        data_mg_ga = data_Mg_Ga(test_dir)
        defect_mg_ga = defect_Mg_Ga(gan_structure)
        defect_entries, plot_data = defect_entries_and_plot_data_Mg_Ga(data_mg_ga, defect_mg_ga)
        stable_entries = stable_entries_Mg_Ga_N(test_dir)
        fed = formation_energy_diagram(data_mg_ga, defect_entries_and_plot_data_Mg_Ga, stable_entries)

        cp_at_point = {}
        for k, v in fed.chempot_limits.items():
            cp_at_point[f"{k}:{v:.2f}"] = set(fed.get_competing_phases_at_chempot_limit(k))

        properties["competing_phases_at_chempot_limits"] = cp_at_point

    except Exception as e:
        pass

    return properties

