def calculate_localized_bands():
    from pathlib import Path
    from pymatgen.io.vasp.outputs import Procar, Vasprun
    from pymatgen.analysis.defects.utils import get_localized_orbitals

    def get_v_ga(test_dir):
        res = dict()
        for q1, q2 in [(0, -1), (-1, 0)]:
            ccd_dir = test_dir / f"v_Ga/ccd_{q1}_{q2}"
            vaspruns = [Vasprun(ccd_dir / f"{i}/vasprun.xml") for i in [0, 1, 2]]
            res[(q1, q2)] = {
                "vaspruns": vaspruns,
                "procar": Procar(ccd_dir / "1/PROCAR"),
            }
        return res

    try:
        v_ga = get_v_ga(Path("tool_source_code/pymatgen-analysis-defects/tests/test_files/"))

        # Calculate localized_bands_set_1
        try:
            vaspruns = v_ga[(0, -1)]["vaspruns"]
            procar = v_ga[(0, -1)]["procar"]
            vr = vaspruns[1]
            bs = vr.get_band_structure()
            localized_bands_set_1 = set()
            for iband, _ikpt, _ispin, _val in get_localized_orbitals(bs, procar=procar):
                localized_bands_set_1.add(iband)
        except Exception:
            localized_bands_set_1 = None

        # Calculate localized_bands_set_2
        try:
            vaspruns = v_ga[(-1, 0)]["vaspruns"]
            procar = v_ga[(-1, 0)]["procar"]
            vr = vaspruns[1]
            bs = vr.get_band_structure()
            localized_bands_set_2 = set()
            for iband, _ikpt, _ispin, _val in get_localized_orbitals(bs, procar=procar, band_window=100):
                localized_bands_set_2.add(iband)
        except Exception:
            localized_bands_set_2 = None

        return {
            "localized_bands_set_1": localized_bands_set_1,
            "localized_bands_set_2": localized_bands_set_2
        }

    except Exception:
        return {
            "localized_bands_set_1": None,
            "localized_bands_set_2": None
        }

def calculate_interstitial_properties():
    from pymatgen.core import Structure, PeriodicSite, Element
    from pymatgen.core.periodic_table import Specie
    from pymatgen.analysis.defects.core import Interstitial
    from pymatgen.analysis.defects.finder import DefectSiteFinder
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files")
    gan_struct = Structure.from_file(file_path / "GaN.vasp")

    # Create interstitial defect
    s = gan_struct.copy()
    inter_fpos = [0, 0, 0.75]
    n_site = PeriodicSite(Specie("N"), inter_fpos, s.lattice)
    inter = Interstitial(s, n_site)

    # Create another interstitial defect for user-defined charge states
    inter2 = Interstitial(s, n_site, user_charges=[-100, 102])

    # Initialize DefectSiteFinder
    finder = DefectSiteFinder()

    # Calculate properties
    properties = {}
    try:
        properties['oxidation_state'] = inter.oxi_state
    except Exception:
        properties['oxidation_state'] = None

    try:
        properties['charge_states'] = inter.get_charge_states()
    except Exception:
        properties['charge_states'] = None

    try:
        properties['fractional_coordinates'] = list(n_site.frac_coords)
    except Exception:
        properties['fractional_coordinates'] = None

    try:
        properties['supercell_formula'] = inter.defect_structure.composition.formula
    except Exception:
        properties['supercell_formula'] = None

    try:
        properties['defect_name'] = inter.name
    except Exception:
        properties['defect_name'] = None

    try:
        properties['defect_string_representation'] = str(inter)
    except Exception:
        properties['defect_string_representation'] = None

    try:
        properties['element_changes'] = inter.element_changes
    except Exception:
        properties['element_changes'] = None

    try:
        properties['latex_name'] = f"${inter.name}$"
    except Exception:
        properties['latex_name'] = None

    try:
        properties['defect_fpos_initial'] = list(finder.get_defect_fpos(inter.defect_structure, s))
    except Exception:
        properties['defect_fpos_initial'] = None

    try:
        # Modify the structure to include the interstitial at a specific position
        target_fpos = [0.3, 0.5, 0.9]
        modified_site = PeriodicSite(Specie("N"), target_fpos, s.lattice)
        inter_modified = Interstitial(s, modified_site)
        properties['defect_fpos_modified'] = list(modified_site.frac_coords)
    except Exception:
        properties['defect_fpos_modified'] = None

    try:
        properties['user_defined_charge_states'] = inter2.get_charge_states()
    except Exception:
        properties['user_defined_charge_states'] = None

    return properties

def calculate_vacancy_properties():
    from pymatgen.core import Structure
    from pymatgen.analysis.defects.core import Vacancy
    from pymatgen.analysis.defects.generators import VacancyGenerator
    from pymatgen.analysis.defects.finder import DefectSiteFinder
    from pymatgen.core.periodic_table import Element
    from pathlib import Path

    file_path = Path("tool_source_code/pymatgen-analysis-defects/tests/test_files")
    gan_struct = Structure.from_file(file_path / "GaN.vasp")

    # Generate vacancy defects
    try:
        s = gan_struct.copy()
        vac = Vacancy(s, s.sites[0])
        vac2 = Vacancy(s, s.sites[1])
    except Exception:
        return {prop: None for prop in [
            "symmetry_equivalence", "vacancy_string_representation", "vacancy_oxidation_state",
            "vacancy_charge_states", "vacancy_multiplicity", "vacancy_supercell_formula",
            "vacancy_name", "vacancy_self_equivalence", "vacancy_element_changes", "vacancy_latex_name"
        ]}

    # Calculate properties
    properties = {}

    # Symmetry equivalence
    try:
        properties["symmetry_equivalence"] = vac.name == vac2.name
    except Exception:
        properties["symmetry_equivalence"] = None

    # Vacancy string representation
    try:
        properties["vacancy_string_representation"] = f"v_{vac.site.specie.symbol}_{vac.site.index}"
    except Exception:
        properties["vacancy_string_representation"] = None

    # Vacancy oxidation state
    try:
        properties["vacancy_oxidation_state"] = vac.oxi_state if vac.oxi_state is not None else 0
    except Exception:
        properties["vacancy_oxidation_state"] = None

    # Vacancy charge states
    try:
        properties["vacancy_charge_states"] = vac.user_charges if vac.user_charges is not None else []
    except Exception:
        properties["vacancy_charge_states"] = None

    # Vacancy multiplicity
    try:
        properties["vacancy_multiplicity"] = vac.get_multiplicity()
    except Exception:
        properties["vacancy_multiplicity"] = None

    # Vacancy supercell formula
    try:
        properties["vacancy_supercell_formula"] = vac.defect_structure.composition.reduced_formula
    except Exception:
        properties["vacancy_supercell_formula"] = None

    # Vacancy name
    try:
        properties["vacancy_name"] = vac.name
    except Exception:
        properties["vacancy_name"] = None

    # Vacancy self equivalence
    try:
        properties["vacancy_self_equivalence"] = vac.name == vac.name
    except Exception:
        properties["vacancy_self_equivalence"] = None

    # Vacancy element changes
    try:
        properties["vacancy_element_changes"] = vac.element_changes
    except Exception:
        properties["vacancy_element_changes"] = None

    # Vacancy LaTeX name
    try:
        properties["vacancy_latex_name"] = f"v_{{{vac.site.specie.symbol}}}"
    except Exception:
        properties["vacancy_latex_name"] = None

    return properties
